{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "This systematic review aims to address the following PIO question: 'What is the effect of social media on prevention and promotion of oral health compared with conventional strategies among lay people of any age without disability or systematic diseases?'. The review encompasses (P) laypeople from diverse backgrounds, including different age groups, genders, socioeconomic statuses, ethnicities without any disability or systematic diseases. The focus is on (I) social media-based interventions that employ a group approach for information dissemination. The desired outcomes include (O) any changes in oral health status, knowledge, beliefs, and attitudes resulting from social media interventions. This includes short and long-term effects, regardless of the duration of follow-up. The full-text articles from 2012 to 2023 focus on randomized controlled trials (RCTs), quasi-randomized trials and field trials were included in the current study.",
      "reason": "The eligibility criteria specify P/I/O (PIO question components), eligible study designs, and follow-up requirement (“regardless of the duration of follow-up”). However, relevant “settings” and other detailed study-characteristic requirements (beyond the intervention approach and designs) are not explicitly described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "The full-text articles from 2012 to 2023 focus on randomized controlled trials (RCTs), quasi-randomized trials and field trials were included in the current study. ... were excluded ... or were published in languages other than English ... The conference proceedings, editorials, commentaries, review articles, pilot studies and all the studies that assessed the quality of the content of social media were excluded.",
      "reason": "The review specifies dissemination/publication years (2012 to 2023) and language (English only). It also mentions types of reports excluded (e.g., editorials, conference proceedings). However, the retrieved evidence does not clearly specify all report-status criteria required (e.g., explicit inclusion/exclusion of unpublished reports)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not distinguish exclusion due to outcomes being not measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "Eight studies employed a design in which two or more groups were compared [14-21], and the rest reported changes before and after the intervention within a single study group [22, 23].",
      "reason": "The evidence describes how included studies compared groups versus before-after designs, but it does not explicitly state what synthesis groups were used in each synthesis or link those groups to specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although inclusion/exclusion criteria are stated, the retrieved evidence does not provide rationales for notable restrictions on study eligibility."
    }
  ],
  "confidence": 62
}

